/* @lc app=leetcode id=2322 lang=kotlin */
class Solution { fun minimumScore(nums: IntArray, edges: Array<IntArray>): Int = Array(nums.size) { mutableListOf<Int>() }.apply { edges.forEach { e -> this[e[0]].add(e[1]).also { this[e[1]].add(e[0]) } } }.let { adj -> IntArray(nums.size).let { tin -> IntArray(nums.size).let { tout -> IntArray(nums.size).let { xor -> IntArray(1).let { timer -> DeepRecursiveFunction<Pair<Int, Int>, Int> { (u, p) -> (timer[0].also { timer[0] += 1 }).also { tin[u] = it }.run { nums[u] }.also { xor[u] = it }.run { adj[u].filter { it != p } }.forEach { v -> xor[u] = xor[u] xor callRecursive(v to u) }.run { timer[0] }.also { tout[u] = it }.run { xor[u] } }.invoke(0 to -1).run { (1 until nums.size).minOf { i -> (i + 1 until nums.size).minOf { j -> (tin[i] >= tin[j] && tout[i] <= tout[j]).let { iInJ -> (tin[j] >= tin[i] && tout[j] <= tout[i]).let { jInI -> (if (iInJ) listOf(xor[i], xor[j] xor xor[i], xor[0] xor xor[j]) else if (jInI) listOf(xor[j], xor[i] xor xor[j], xor[0] xor xor[i]) else listOf(xor[i], xor[j], xor[0] xor xor[i] xor xor[j])).let { it.maxOrNull()!! - it.minOrNull()!! } } } } } } } } } } } }